 choose=[["___ the cost, the plan is useful.","Despite",["Despite of","Although","Despite that"],"<i>Despite</i> + noun."],["___ it is costly, the plan is useful.","Although",["Despite","In spite","Despite of"],"<i>Although</i> + clause."],["In spite ___ the delay, we finished.","of",["from","to","for"],"<i>in spite of</i>."],["___ being tired, she kept working.","Despite",["Although","However","Because"],"<i>Despite + -ing</i>."],["___ some people prefer cars, others choose buses.","While",["Despite","In spite","Although of"],"<i>While</i> shows contrast."]],
